static char const* PC_REMOTE_PAGE = R"GDPAGE(<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>GD PC Remote</title>
<style>
  :root {
    --bg: #07080f; --panel: #141829; --line: #283050; --text: #e8ebff; --dim: #8a90b8;
    --accent: #3ee0ff; --green: #4dff88; --red: #ff4d6d; --yellow: #ffd84d;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; background: var(--bg); color: var(--text); font-family: "Segoe UI", system-ui, sans-serif; overflow: hidden; }
  body { display: flex; flex-direction: column; }
  .bar { display: flex; align-items: center; gap: 8px; padding: 7px 10px; background: var(--panel); border-bottom: 1px solid var(--line); flex-wrap: wrap; }
  .bar h1 { font-size: 15px; margin: 0 8px 0 2px; white-space: nowrap; }
  .bar h1 span { color: var(--accent); }
  input, select { background: #0b0e1a; color: var(--text); border: 1px solid var(--line); border-radius: 7px; padding: 5px 7px; font-size: 13px; font-family: inherit; }
  #ip { width: 140px; } #port { width: 62px; }
  button { font-family: inherit; cursor: pointer; background: #232a4a; color: var(--text); border: 1px solid var(--line); border-radius: 7px; padding: 5px 11px; font-size: 13px; }
  button:hover { border-color: var(--accent); }
  .dot { width: 10px; height: 10px; border-radius: 50%; background: var(--red); box-shadow: 0 0 7px var(--red); flex: none; }
  .dot.on { background: var(--green); box-shadow: 0 0 7px var(--green); }
  .dot.wait { background: var(--yellow); box-shadow: 0 0 7px var(--yellow); }
  #status { font-size: 12px; color: var(--dim); min-width: 170px; white-space: nowrap; }
  .grp { display: flex; align-items: center; gap: 5px; font-size: 12px; color: var(--dim); }
  .sp { flex: 1; }

  #stage { flex: 1; min-height: 0; overflow: hidden; display: flex; align-items: center; justify-content: center; position: relative; background: #000; }
  #screen { display: none; touch-action: none; cursor: crosshair; image-rendering: auto; outline: none; }
  #empty { color: var(--dim); text-align: center; line-height: 1.7; font-size: 14px; padding: 20px; max-width: 640px; }
  #empty b { color: var(--text); }
  kbd { background: #232a4a; border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 5px; padding: 1px 6px; font-size: 12px; color: var(--text); }
  #focusHint { position: absolute; top: 10px; left: 50%; transform: translateX(-50%); background: rgba(20,24,41,.92); border: 1px solid var(--line); border-radius: 8px; padding: 6px 12px; font-size: 12px; color: var(--dim); display: none; pointer-events: none; }
  .help { font-size: 12px; color: var(--dim); padding: 5px 12px; background: var(--panel); border-top: 1px solid var(--line); }
</style>
</head>
<body>
<div class="bar">
  <h1>GD <span>PC Remote</span></h1>
  <div class="dot" id="dot"></div>
  <input id="ip" placeholder="Tablet IP" spellcheck="false">
  <input id="port" value="7777">
  <button id="connectBtn">Connect</button>
  <span id="status">Not connected</span>
  <span class="sp"></span>
  <label class="grp">Size
    <select id="cfgWidth"><option>640</option><option selected>854</option><option>960</option><option>1280</option><option>1600</option></select></label>
  <label class="grp">FPS
    <select id="cfgFps"><option>15</option><option>24</option><option selected>30</option><option>45</option><option>60</option></select></label>
  <label class="grp">Quality
    <select id="cfgQuality"><option value="40">Low</option><option value="60" selected>Medium</option><option value="75">High</option><option value="88">Max</option></select></label>
  <button id="backBtn" title="Android back button (Esc)">◀ Back</button>
  <button id="zoomOut" title="Pinch zoom out (wheel down)">−</button>
  <button id="zoomIn" title="Pinch zoom in (wheel up)">+</button>
  <button id="fsBtn" title="Fullscreen (also lets the page capture Esc / Ctrl shortcuts)">⛶</button>
</div>

<div id="stage">
  <canvas id="screen" tabindex="0"></canvas>
  <div id="empty">
    Open Geometry Dash on the tablet with the <b>PC Remote</b> mod.<br>
    The main menu shows the address at the bottom, e.g. <kbd>192.168.1.25:7777</kbd>.<br>
    Type the IP above and press <b>Connect</b>, or open <kbd>http://IP:7777</kbd> directly in Chrome / Edge.<br>
    PC and tablet must be on the same Wi-Fi.
  </div>
  <div id="focusHint">Click the game to send your keyboard to it</div>
</div>

<div class="help">
  <b>Mouse</b> left = tap / drag · <b>right-drag</b> = two-finger pan · <b>wheel</b> = pinch zoom ·
  <b>Space / W / ↑</b> jump · <b>A D ← →</b> move · <b>Esc</b> = back / pause · all other keys go to GD (editor shortcuts, typing text)
</div>

<script>
(() => {
  const $ = (id) => document.getElementById(id);
  const ipEl = $("ip"), portEl = $("port"), dot = $("dot"), statusEl = $("status"), connectBtn = $("connectBtn");
  const canvas = $("screen"), ctx = canvas.getContext("2d", { alpha: false, desynchronized: true }), empty = $("empty"), focusHint = $("focusHint");
  const cfgWidth = $("cfgWidth"), cfgFps = $("cfgFps"), cfgQuality = $("cfgQuality");

  // ---------- saved settings ----------
  function load() {
    try { return JSON.parse(localStorage.getItem("gdRemote2") || "{}"); } catch (e) { return {}; }
  }
  function save() {
    try {
      localStorage.setItem("gdRemote2", JSON.stringify({
        ip: ipEl.value.trim(), port: portEl.value.trim(),
        w: cfgWidth.value, fps: cfgFps.value, q: cfgQuality.value,
      }));
    } catch (e) {}
  }
  const saved = load();
  if (saved.ip) ipEl.value = saved.ip;
  if (saved.port) portEl.value = saved.port;
  if (saved.w) cfgWidth.value = saved.w;
  if (saved.fps) cfgFps.value = saved.fps;
  if (saved.q) cfgQuality.value = saved.q;

  const servedByTablet = location.protocol === "http:" && location.hostname && location.hostname !== "localhost";
  if (servedByTablet) { ipEl.value = location.hostname; portEl.value = location.port || "80"; }

  // ---------- connection ----------
  let ws = null, wantConnected = false, reconnectTimer = null, pingTimer = null;
  let lastPing = 0, frames = 0, bytes = 0, fpsShown = 0, kbShown = 0, hasFrame = false;
  let capMs = 0, encMs = 0, decMs = 0, gpu = true, frameSeq = 0, drawnSeq = 0;

  function setStatus(state, text) {
    dot.className = "dot" + (state === "on" ? " on" : state === "wait" ? " wait" : "");
    statusEl.textContent = text;
    connectBtn.textContent = wantConnected ? "Disconnect" : "Connect";
  }
  const isOpen = () => ws && ws.readyState === WebSocket.OPEN;
  function send(msg) { if (isOpen()) ws.send(msg); }
  function sendConfig() { send(`cfg ${cfgWidth.value} ${cfgFps.value} ${cfgQuality.value}`); save(); }
  [cfgWidth, cfgFps, cfgQuality].forEach((el) => el.addEventListener("change", sendConfig));

  function connect() {
    const ip = ipEl.value.trim(), port = portEl.value.trim() || "7777";
    if (!ip) { setStatus("off", "Enter the tablet IP"); ipEl.focus(); return; }
    save();
    wantConnected = true;
    clearTimeout(reconnectTimer);
    if (ws) { ws.onclose = null; ws.close(); }
    setStatus("wait", "Connecting…");
    try { ws = new WebSocket(`ws://${ip}:${port}`); } catch (e) { wantConnected = false; setStatus("off", "Bad address"); return; }
    ws.binaryType = "arraybuffer";

    ws.onopen = () => {
      setStatus("on", "Connected, waiting for video…");
      sendConfig();
      clearInterval(pingTimer);
      pingTimer = setInterval(() => {
        send("ping " + performance.now().toFixed(1));
        fpsShown = frames; kbShown = Math.round(bytes / 1024); frames = 0; bytes = 0;
        updateStats();
      }, 1000);
      canvas.focus();
    };
    ws.onmessage = (ev) => {
      if (typeof ev.data === "string") {
        const p = ev.data.split(" ");
        if (p[0] === "pong") { lastPing = Math.round(performance.now() - parseFloat(p[1])); updateStats(); }
        return;
      }
      showFrame(ev.data);
    };
    ws.onclose = () => {
      clearInterval(pingTimer);
      releaseEverything(false);
      if (wantConnected) { setStatus("wait", "Lost connection, retrying…"); reconnectTimer = setTimeout(connect, 2000); }
      else setStatus("off", "Not connected");
    };
  }
  function disconnect() {
    wantConnected = false;
    clearTimeout(reconnectTimer); clearInterval(pingTimer);
    releaseEverything(true);
    if (ws) ws.close();
    setStatus("off", "Not connected");
  }
  connectBtn.onclick = () => (wantConnected ? disconnect() : connect());
  [ipEl, portEl].forEach((el) => el.addEventListener("keydown", (e) => { if (e.key === "Enter") connect(); }));

  function updateStats() {
    if (!isOpen()) return;
    setStatus("on", hasFrame
      ? `${fpsShown} fps · Wi-Fi ${lastPing} ms · ${kbShown} KB/s · tablet ${capMs.toFixed(1)}+${encMs.toFixed(0)} ms${gpu ? "" : " (CPU)"} · PC ${decMs.toFixed(0)} ms`
      : `Connected · ${lastPing} ms · waiting for video`);
  }

  // ---------- video ----------
  // Frame = header + several JPEG strips (encoded in parallel on the tablet)
  async function showFrame(buf) {
    const seq = ++frameSeq;
    bytes += buf.byteLength;
    const t0 = performance.now();
    try {
      const dv = new DataView(buf);
      const W = dv.getUint16(0, true), H = dv.getUint16(2, true), n = dv.getUint8(4);
      capMs = dv.getUint16(5, true) / 10; encMs = dv.getUint16(7, true) / 10; gpu = (dv.getUint8(9) & 1) === 1;
      let off = 10;
      const parts = [];
      for (let i = 0; i < n; i++) {
        const y = dv.getUint16(off, true), len = dv.getUint32(off + 4, true);
        off += 8;
        parts.push({ y, blob: new Blob([new Uint8Array(buf, off, len)], { type: "image/jpeg" }) });
        off += len;
      }
      const bmps = await Promise.all(parts.map((p) => createImageBitmap(p.blob)));
      if (seq > drawnSeq) {           // never draw an older frame over a newer one
        drawnSeq = seq;
        if (canvas.width !== W || canvas.height !== H) { canvas.width = W; canvas.height = H; fitCanvas(); }
        bmps.forEach((b, i) => ctx.drawImage(b, 0, parts[i].y));
        frames++;
        decMs = decMs * 0.8 + (performance.now() - t0) * 0.2;
        if (!hasFrame) { hasFrame = true; canvas.style.display = "block"; empty.style.display = "none"; canvas.focus(); }
      }
      bmps.forEach((b) => b.close());
    } catch (e) { /* bad frame, skip */ }
    send("ack"); // lets the tablet send another frame
  }

  // Scale the video to fill the window while keeping its shape
  const stageEl = $("stage");
  function fitCanvas() {
    if (!canvas.width) return;
    const sw = stageEl.clientWidth, sh = stageEl.clientHeight;
    const scale = Math.min(sw / canvas.width, sh / canvas.height);
    canvas.style.width = Math.floor(canvas.width * scale) + "px";
    canvas.style.height = Math.floor(canvas.height * scale) + "px";
  }
  window.addEventListener("resize", fitCanvas);
  if (window.ResizeObserver) new ResizeObserver(fitCanvas).observe(stageEl);
  document.addEventListener("fullscreenchange", () => setTimeout(fitCanvas, 50));

  // ---------- touches ----------
  // Mouse left = finger 0, touch-screen fingers = 1..7, right-drag = fingers 8+9, pinch = 10+11
  function norm(clientX, clientY) {
    const r = canvas.getBoundingClientRect();
    return [
      Math.min(1, Math.max(0, (clientX - r.left) / r.width)),
      Math.min(1, Math.max(0, (clientY - r.top) / r.height)),
    ];
  }
  const fmt = (v) => v.toFixed(4);
  function touch(phase, id, x, y) { send(`t ${phase} ${id} ${fmt(x)} ${fmt(y)}`); }

  const activePointers = new Map(); // pointerId -> {fingers:[ids], last:[x,y]}
  let nextTouchId = 1;
  const PAN_GAP = 0.04;

  canvas.addEventListener("pointerdown", (e) => {
    if (!isOpen()) return;
    e.preventDefault();
    canvas.focus();
    canvas.setPointerCapture(e.pointerId);
    const [x, y] = norm(e.clientX, e.clientY);
    let fingers;
    if (e.pointerType === "mouse" && e.button === 2) {
      fingers = [8, 9];
      touch("d", 8, x - PAN_GAP, y); touch("d", 9, x + PAN_GAP, y);
    } else if (e.pointerType === "mouse") {
      if (e.button !== 0) return;
      fingers = [0];
      touch("d", 0, x, y);
    } else {
      const id = nextTouchId; nextTouchId = nextTouchId >= 7 ? 1 : nextTouchId + 1;
      fingers = [id];
      touch("d", id, x, y);
    }
    activePointers.set(e.pointerId, { fingers, last: [x, y], pending: null });
  });

  canvas.addEventListener("pointermove", (e) => {
    const p = activePointers.get(e.pointerId);
    if (!p) return;
    p.pending = norm(e.clientX, e.clientY);
  });

  function endPointer(e) {
    const p = activePointers.get(e.pointerId);
    if (!p) return;
    const [x, y] = p.pending || p.last;
    if (p.fingers.length === 2) { touch("u", p.fingers[0], x - PAN_GAP, y); touch("u", p.fingers[1], x + PAN_GAP, y); }
    else touch("u", p.fingers[0], x, y);
    activePointers.delete(e.pointerId);
  }
  canvas.addEventListener("pointerup", endPointer);
  canvas.addEventListener("pointercancel", endPointer);
  canvas.addEventListener("contextmenu", (e) => e.preventDefault());

  // Send moves at most once per animation frame
  function flushMoves() {
    for (const p of activePointers.values()) {
      if (!p.pending) continue;
      const [x, y] = p.pending;
      if (x !== p.last[0] || y !== p.last[1]) {
        if (p.fingers.length === 2) { touch("m", p.fingers[0], x - PAN_GAP, y); touch("m", p.fingers[1], x + PAN_GAP, y); }
        else touch("m", p.fingers[0], x, y);
        p.last = [x, y];
      }
      p.pending = null;
    }
    requestAnimationFrame(flushMoves);
  }
  requestAnimationFrame(flushMoves);

  // ---------- pinch zoom (wheel and +/- buttons) ----------
  let pinchBusy = false;
  function pinch(zoomIn, cx = 0.5, cy = 0.5) {
    if (!isOpen() || pinchBusy) return;
    pinchBusy = true;
    const steps = 6, start = 0.06, end = zoomIn ? 0.14 : 0.02;
    let i = 0;
    const at = (gap) => [[cx - gap, cy], [cx + gap, cy]];
    let [a, b] = at(start);
    touch("d", 10, a[0], a[1]); touch("d", 11, b[0], b[1]);
    const timer = setInterval(() => {
      i++;
      const gap = start + (end - start) * (i / steps);
      [a, b] = at(gap);
      touch("m", 10, a[0], a[1]); touch("m", 11, b[0], b[1]);
      if (i >= steps) {
        clearInterval(timer);
        touch("u", 10, a[0], a[1]); touch("u", 11, b[0], b[1]);
        pinchBusy = false;
      }
    }, 16);
  }
  canvas.addEventListener("wheel", (e) => {
    e.preventDefault();
    const [x, y] = norm(e.clientX, e.clientY);
    pinch(e.deltaY < 0, Math.min(0.85, Math.max(0.15, x)), y);
  }, { passive: false });
  $("zoomIn").onclick = () => pinch(true);
  $("zoomOut").onclick = () => pinch(false);

  // ---------- keyboard ----------
  const keysDown = new Set();
  const PASS_THROUGH = new Set(["F5", "F11", "F12"]);
  function mods(e) { return (e.shiftKey ? 1 : 0) | (e.ctrlKey ? 2 : 0) | (e.altKey ? 4 : 0); }

  function keyActive() { return isOpen() && document.activeElement === canvas; }

  window.addEventListener("keydown", (e) => {
    if (!keyActive()) return;
    if (PASS_THROUGH.has(e.code)) return;
    e.preventDefault();
    if (e.code === "Escape") { if (!e.repeat) send("back"); return; }
    const code = e.keyCode;
    if (!code) return;
    if (e.repeat) send(`k r ${code} ${mods(e)}`);
    else { keysDown.add(code); send(`k d ${code} ${mods(e)}`); }
    if (e.key === "Backspace") send("bs");
    else if (e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) send("x " + e.key);
  });
  window.addEventListener("keyup", (e) => {
    const code = e.keyCode;
    if (!keysDown.has(code)) return;
    keysDown.delete(code);
    send(`k u ${code} ${mods(e)}`);
  });

  function releaseEverything(notify) {
    if (notify) {
      for (const code of keysDown) send(`k u ${code} 0`);
      for (const [, p] of activePointers) {
        const [x, y] = p.last;
        for (const f of p.fingers) touch("u", f, x, y);
      }
    }
    keysDown.clear();
    activePointers.clear();
  }
  window.addEventListener("blur", () => releaseEverything(true));

  canvas.addEventListener("focus", () => (focusHint.style.display = "none"));
  canvas.addEventListener("blur", () => { if (hasFrame) focusHint.style.display = "block"; releaseEverything(true); });

  // ---------- buttons ----------
  $("backBtn").onclick = () => { send("back"); canvas.focus(); };
  $("fsBtn").onclick = async () => {
    const stage = $("stage");
    if (document.fullscreenElement) { document.exitFullscreen(); return; }
    try {
      await stage.requestFullscreen();
      if (navigator.keyboard && navigator.keyboard.lock) navigator.keyboard.lock().catch(() => {});
    } catch (e) {}
    canvas.focus();
  };

  setStatus("off", "Not connected");
  if (servedByTablet) connect();
})();
</script>
</body>
</html>
)GDPAGE";
